'use client';

import {
  Combobox as ComboboxPrimitive,
  type CollectionItem,
  type ComboboxRootComponent,
  type ComboboxRootProps,
  useComboboxContext,
} from '@ark-ui/react/combobox';
import { Dialog as DialogPrimitive, useDialogContext } from '@ark-ui/react/dialog';
import type { HTMLArkProps } from '@ark-ui/react/factory';
import { ark } from '@ark-ui/react/factory';
import { isHotKey } from '@ark-ui/react/hotkeys';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef, ForwardedRef } from 'react';
import { forwardRef, useEffect } from 'react';
import { a11yLabels } from '@/lib/moduix/a11yLabels';
import { CheckIcon, CloseIcon, SearchIcon } from '@/lib/moduix/icons/ui';
import {
  OverlayPortal,
  OverlayPortalProvider,
  type OverlayPortalProps,
} from '@/lib/moduix/overlayPortal';
import closeButtonStyles from '../close-button/CloseButton.module.css';
import { Kbd } from '../kbd';
import { ScrollArea, ScrollAreaContent, ScrollAreaViewport } from '../scroll-area';
import styles from './CommandPalette.module.css';

type CommandPaletteShortcutProps = {
  shortcut?: false | string;
};

type CommandPaletteRootProps = ComponentProps<typeof DialogPrimitive.Root> &
  CommandPaletteShortcutProps &
  OverlayPortalProps;

type CommandPaletteRootProviderProps = ComponentProps<typeof DialogPrimitive.RootProvider> &
  CommandPaletteShortcutProps &
  OverlayPortalProps;

function CommandPaletteShortcut({ shortcut }: { shortcut: string }) {
  const dialog = useDialogContext();

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (
        event.defaultPrevented ||
        event.repeat ||
        event.isComposing ||
        !isHotKey(shortcut, event, {
          enableOnContentEditable: dialog.open,
          enableOnFormTags: dialog.open,
        })
      ) {
        return;
      }

      event.preventDefault();
      dialog.setOpen(!dialog.open);
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [dialog, shortcut]);

  return null;
}

function CommandPalette({
  shortcut = false,
  lazyMount = true,
  unmountOnExit = true,
  portalled,
  portalRef,
  children,
  ...props
}: CommandPaletteRootProps) {
  return (
    <OverlayPortalProvider portalled={portalled} portalRef={portalRef}>
      <DialogPrimitive.Root lazyMount={lazyMount} unmountOnExit={unmountOnExit} {...props}>
        {shortcut ? <CommandPaletteShortcut shortcut={shortcut} /> : null}
        {children}
      </DialogPrimitive.Root>
    </OverlayPortalProvider>
  );
}

function CommandPaletteRootProvider({
  shortcut = false,
  lazyMount = true,
  unmountOnExit = true,
  portalled,
  portalRef,
  children,
  ...props
}: CommandPaletteRootProviderProps) {
  return (
    <OverlayPortalProvider portalled={portalled} portalRef={portalRef}>
      <DialogPrimitive.RootProvider lazyMount={lazyMount} unmountOnExit={unmountOnExit} {...props}>
        {shortcut ? <CommandPaletteShortcut shortcut={shortcut} /> : null}
        {children}
      </DialogPrimitive.RootProvider>
    </OverlayPortalProvider>
  );
}

const CommandPaletteTrigger = forwardRef<
  ComponentRef<typeof DialogPrimitive.Trigger>,
  ComponentProps<typeof DialogPrimitive.Trigger>
>(function CommandPaletteTrigger(props, ref) {
  return <DialogPrimitive.Trigger ref={ref} {...props} data-slot="command-palette-trigger" />;
});

const CommandPaletteBackdrop = forwardRef<
  ComponentRef<typeof DialogPrimitive.Backdrop>,
  ComponentProps<typeof DialogPrimitive.Backdrop>
>(function CommandPaletteBackdrop({ className, ...props }, ref) {
  return (
    <OverlayPortal>
      <DialogPrimitive.Backdrop
        ref={ref}
        className={clsx(styles.backdrop, className)}
        {...props}
        data-slot="command-palette-backdrop"
      />
    </OverlayPortal>
  );
});

const CommandPalettePositioner = forwardRef<
  ComponentRef<typeof DialogPrimitive.Positioner>,
  ComponentProps<typeof DialogPrimitive.Positioner>
>(function CommandPalettePositioner({ className, ...props }, ref) {
  return (
    <OverlayPortal>
      <DialogPrimitive.Positioner
        ref={ref}
        className={clsx(styles.positioner, className)}
        {...props}
        data-slot="command-palette-positioner"
      />
    </OverlayPortal>
  );
});

const CommandPaletteContent = forwardRef<
  ComponentRef<typeof DialogPrimitive.Content>,
  ComponentProps<typeof DialogPrimitive.Content>
>(function CommandPaletteContent({ className, ...props }, ref) {
  return (
    <DialogPrimitive.Content
      ref={ref}
      className={clsx(styles.content, className)}
      {...props}
      data-slot="command-palette-content"
    />
  );
});

const CommandPalettePanel = forwardRef<
  ComponentRef<typeof DialogPrimitive.Content>,
  ComponentProps<typeof DialogPrimitive.Content>
>(function CommandPalettePanel(props, ref) {
  return (
    <>
      <CommandPaletteBackdrop />
      <CommandPalettePositioner>
        <CommandPaletteContent ref={ref} {...props} />
      </CommandPalettePositioner>
    </>
  );
});

const CommandPaletteTitle = forwardRef<
  ComponentRef<typeof DialogPrimitive.Title>,
  ComponentProps<typeof DialogPrimitive.Title>
>(function CommandPaletteTitle({ className, ...props }, ref) {
  return (
    <DialogPrimitive.Title
      ref={ref}
      className={clsx(styles.title, className)}
      {...props}
      data-slot="command-palette-title"
    />
  );
});

const CommandPaletteDescription = forwardRef<
  ComponentRef<typeof DialogPrimitive.Description>,
  ComponentProps<typeof DialogPrimitive.Description>
>(function CommandPaletteDescription({ className, ...props }, ref) {
  return (
    <DialogPrimitive.Description
      ref={ref}
      className={clsx(styles.description, className)}
      {...props}
      data-slot="command-palette-description"
    />
  );
});

const CommandPaletteHeader = forwardRef<HTMLDivElement, HTMLArkProps<'div'>>(
  function CommandPaletteHeader({ className, ...props }, ref) {
    return (
      <ark.div
        ref={ref}
        className={clsx(styles.header, className)}
        {...props}
        data-slot="command-palette-header"
      />
    );
  },
);

const CommandPaletteCombobox = forwardRef(function CommandPaletteCombobox<T extends CollectionItem>(
  {
    className,
    open = true,
    inputBehavior = 'autohighlight',
    selectionBehavior = 'preserve',
    closeOnSelect = true,
    disableLayer = true,
    onSelect,
    ...props
  }: ComboboxRootProps<T>,
  ref: ForwardedRef<HTMLDivElement>,
) {
  const dialog = useDialogContext();
  const handleSelect: ComboboxRootProps<T>['onSelect'] = (details) => {
    onSelect?.(details);

    if (closeOnSelect) {
      dialog.setOpen(false);
    }
  };

  return (
    <ComboboxPrimitive.Root
      ref={ref}
      className={clsx(styles.combobox, className)}
      open={open}
      inputBehavior={inputBehavior}
      selectionBehavior={selectionBehavior}
      closeOnSelect={closeOnSelect}
      disableLayer={disableLayer}
      onSelect={handleSelect}
      {...props}
      data-slot="command-palette-combobox"
    />
  );
}) as ComboboxRootComponent;

const CommandPaletteControl = forwardRef<
  ComponentRef<typeof ComboboxPrimitive.Control>,
  ComponentProps<typeof ComboboxPrimitive.Control>
>(function CommandPaletteControl({ className, ...props }, ref) {
  return (
    <ComboboxPrimitive.Control
      ref={ref}
      className={clsx(styles.control, className)}
      {...props}
      data-slot="command-palette-control"
    />
  );
});

const CommandPaletteInput = forwardRef<
  ComponentRef<typeof ComboboxPrimitive.Input>,
  ComponentProps<typeof ComboboxPrimitive.Input>
>(function CommandPaletteInput({ className, ...props }, ref) {
  return (
    <ComboboxPrimitive.Input
      ref={ref}
      className={clsx(styles.input, className)}
      {...props}
      data-slot="command-palette-input"
    />
  );
});

const CommandPaletteSearch = forwardRef<
  ComponentRef<typeof ComboboxPrimitive.Input>,
  ComponentProps<typeof ComboboxPrimitive.Input>
>(function CommandPaletteSearch(
  { 'aria-label': ariaLabel, 'aria-labelledby': ariaLabelledBy, ...props },
  ref,
) {
  return (
    <CommandPaletteControl>
      <SearchIcon data-slot="command-palette-search-icon" className={styles.searchIcon} />
      <CommandPaletteInput
        ref={ref}
        aria-label={ariaLabel ?? (ariaLabelledBy == null ? a11yLabels.searchCommands : undefined)}
        aria-labelledby={ariaLabelledBy}
        {...props}
      />
      <CommandPaletteClearTrigger />
    </CommandPaletteControl>
  );
});

const CommandPaletteClearTrigger = forwardRef<
  ComponentRef<typeof ComboboxPrimitive.ClearTrigger>,
  ComponentProps<typeof ComboboxPrimitive.ClearTrigger>
>(function CommandPaletteClearTrigger(
  {
    asChild,
    className,
    children,
    onClick,
    'aria-label': ariaLabel,
    'aria-labelledby': ariaLabelledBy,
    ...props
  },
  ref,
) {
  const combobox = useComboboxContext();

  return (
    <ComboboxPrimitive.ClearTrigger
      ref={ref}
      asChild={asChild}
      aria-label={
        ariaLabel ?? (!asChild && ariaLabelledBy == null ? a11yLabels.clearSearch : undefined)
      }
      aria-labelledby={ariaLabelledBy}
      className={clsx(closeButtonStyles.root, styles.clearTrigger, className)}
      {...props}
      hidden={combobox.inputValue === ''}
      onClick={(event) => {
        onClick?.(event);

        // Clear only the query; Ark's own handler would also clear the selected value.
        if (!event.defaultPrevented) {
          event.preventDefault();
          combobox.setInputValue('');
        }
      }}
      data-slot="command-palette-clear-trigger"
    >
      {children ?? <CloseIcon />}
    </ComboboxPrimitive.ClearTrigger>
  );
});

const CommandPaletteList = forwardRef<
  ComponentRef<typeof ComboboxPrimitive.Content>,
  ComponentProps<typeof ComboboxPrimitive.Content>
>(function CommandPaletteList({ className, children, ...props }, ref) {
  return (
    <ComboboxPrimitive.Content
      ref={ref}
      className={clsx(styles.list, className)}
      {...props}
      data-slot="command-palette-list"
    >
      <ScrollArea className={styles.scrollArea}>
        <ScrollAreaViewport className={styles.scrollViewport}>
          <ScrollAreaContent className={styles.scrollContent}>{children}</ScrollAreaContent>
        </ScrollAreaViewport>
      </ScrollArea>
    </ComboboxPrimitive.Content>
  );
});

const CommandPaletteEmpty = forwardRef<
  ComponentRef<typeof ComboboxPrimitive.Empty>,
  ComponentProps<typeof ComboboxPrimitive.Empty>
>(function CommandPaletteEmpty({ className, ...props }, ref) {
  return (
    <ComboboxPrimitive.Empty
      ref={ref}
      className={clsx(styles.empty, className)}
      {...props}
      data-slot="command-palette-empty"
    />
  );
});

const CommandPaletteItemGroup = forwardRef<
  ComponentRef<typeof ComboboxPrimitive.ItemGroup>,
  ComponentProps<typeof ComboboxPrimitive.ItemGroup>
>(function CommandPaletteItemGroup({ className, ...props }, ref) {
  return (
    <ComboboxPrimitive.ItemGroup
      ref={ref}
      className={clsx(styles.itemGroup, className)}
      {...props}
      data-slot="command-palette-item-group"
    />
  );
});

const CommandPaletteItemGroupLabel = forwardRef<
  ComponentRef<typeof ComboboxPrimitive.ItemGroupLabel>,
  ComponentProps<typeof ComboboxPrimitive.ItemGroupLabel>
>(function CommandPaletteItemGroupLabel({ className, ...props }, ref) {
  return (
    <ComboboxPrimitive.ItemGroupLabel
      ref={ref}
      className={clsx(styles.itemGroupLabel, className)}
      {...props}
      data-slot="command-palette-item-group-label"
    />
  );
});

const CommandPaletteItem = forwardRef<
  ComponentRef<typeof ComboboxPrimitive.Item>,
  ComponentProps<typeof ComboboxPrimitive.Item>
>(function CommandPaletteItem({ className, ...props }, ref) {
  return (
    <ComboboxPrimitive.Item
      ref={ref}
      className={clsx(styles.item, className)}
      {...props}
      data-slot="command-palette-item"
    />
  );
});

const CommandPaletteItemText = forwardRef<
  ComponentRef<typeof ComboboxPrimitive.ItemText>,
  ComponentProps<typeof ComboboxPrimitive.ItemText>
>(function CommandPaletteItemText({ className, ...props }, ref) {
  return (
    <ComboboxPrimitive.ItemText
      ref={ref}
      className={clsx(styles.itemText, className)}
      {...props}
      data-slot="command-palette-item-text"
    />
  );
});

const CommandPaletteItemIndicator = forwardRef<
  ComponentRef<typeof ComboboxPrimitive.ItemIndicator>,
  ComponentProps<typeof ComboboxPrimitive.ItemIndicator>
>(function CommandPaletteItemIndicator({ className, children, ...props }, ref) {
  return (
    <ComboboxPrimitive.ItemIndicator
      ref={ref}
      className={clsx(styles.itemIndicator, className)}
      {...props}
      data-slot="command-palette-item-indicator"
    >
      {children ?? <CheckIcon />}
    </ComboboxPrimitive.ItemIndicator>
  );
});

const CommandPaletteItemIcon = forwardRef<HTMLSpanElement, HTMLArkProps<'span'>>(
  function CommandPaletteItemIcon({ className, ...props }, ref) {
    return (
      <ark.span
        ref={ref}
        className={clsx(styles.itemIcon, className)}
        {...props}
        data-slot="command-palette-item-icon"
      />
    );
  },
);

const CommandPaletteItemLabel = forwardRef<HTMLSpanElement, HTMLArkProps<'span'>>(
  function CommandPaletteItemLabel({ className, ...props }, ref) {
    return (
      <ark.span
        ref={ref}
        className={clsx(styles.itemLabel, className)}
        {...props}
        data-slot="command-palette-item-label"
      />
    );
  },
);

const CommandPaletteItemDescription = forwardRef<HTMLSpanElement, HTMLArkProps<'span'>>(
  function CommandPaletteItemDescription({ className, ...props }, ref) {
    return (
      <ark.span
        ref={ref}
        className={clsx(styles.itemDescription, className)}
        {...props}
        data-slot="command-palette-item-description"
      />
    );
  },
);

const CommandPaletteItemMeta = forwardRef<HTMLSpanElement, HTMLArkProps<'span'>>(
  function CommandPaletteItemMeta({ className, ...props }, ref) {
    return (
      <ark.span
        ref={ref}
        className={clsx(styles.itemMeta, className)}
        {...props}
        data-slot="command-palette-item-meta"
      />
    );
  },
);

const CommandPaletteSeparator = forwardRef<HTMLDivElement, HTMLArkProps<'div'>>(
  function CommandPaletteSeparator({ className, ...props }, ref) {
    return (
      <ark.div
        ref={ref}
        role="separator"
        className={clsx(styles.separator, className)}
        {...props}
        data-slot="command-palette-separator"
      />
    );
  },
);

const CommandPaletteFooter = forwardRef<HTMLDivElement, HTMLArkProps<'div'>>(
  function CommandPaletteFooter({ className, ...props }, ref) {
    return (
      <ark.div
        ref={ref}
        className={clsx(styles.footer, className)}
        {...props}
        data-slot="command-palette-footer"
      />
    );
  },
);

const CommandPaletteKbd = forwardRef<ComponentRef<typeof Kbd>, ComponentProps<typeof Kbd>>(
  function CommandPaletteKbd({ className, ...props }, ref) {
    return (
      <Kbd
        ref={ref}
        className={clsx(styles.kbd, className)}
        {...props}
        data-slot="command-palette-kbd"
      />
    );
  },
);

export {
  CommandPalette,
  CommandPaletteBackdrop,
  CommandPaletteClearTrigger,
  CommandPaletteCombobox,
  CommandPaletteContent,
  CommandPaletteControl,
  CommandPaletteDescription,
  CommandPaletteEmpty,
  CommandPaletteFooter,
  CommandPaletteHeader,
  CommandPaletteInput,
  CommandPaletteItem,
  CommandPaletteItemDescription,
  CommandPaletteItemGroup,
  CommandPaletteItemGroupLabel,
  CommandPaletteItemIcon,
  CommandPaletteItemIndicator,
  CommandPaletteItemLabel,
  CommandPaletteItemMeta,
  CommandPaletteItemText,
  CommandPaletteKbd,
  CommandPaletteList,
  CommandPalettePanel,
  CommandPalettePositioner,
  CommandPaletteRootProvider,
  CommandPaletteSearch,
  CommandPaletteSeparator,
  CommandPaletteTitle,
  CommandPaletteTrigger,
};

export type { CommandPaletteRootProps, CommandPaletteRootProviderProps };

@layer moduix.components {
  .backdrop {
    position: fixed;
    z-index: calc(var(--z-index, var(--moduix-z-popup)) - 1);
    inset: 0;
    background-color: var(--moduix-backdrop-bg, var(--moduix-color-overlay));
    backdrop-filter: var(--moduix-backdrop-filter, blur(4px));

    &[data-state='open'] {
      animation: global(moduix-command-palette-backdrop-in) var(--moduix-transition-default);
    }

    &[data-state='closed'] {
      animation: global(moduix-command-palette-backdrop-out) var(--moduix-transition-default)
        forwards;
    }
  }

  .positioner {
    box-sizing: border-box;
    position: fixed;
    z-index: var(--z-index, var(--moduix-z-popup));
    inset: 0;
    display: grid;
    align-items: start;
    justify-items: center;
    overflow: hidden;
    overscroll-behavior: contain;
    padding: 10dvh var(--moduix-spacing-4) var(--moduix-spacing-4);
  }

  .content {
    z-index: calc(var(--moduix-z-popup) + var(--layer-index, 0));
    box-sizing: border-box;
    display: flex;
    width: var(--moduix-command-palette-width, 37.5rem);
    max-width: 100%;
    max-height: min(var(--moduix-command-palette-max-height, 34rem), calc(100dvh - 5rem));
    flex-direction: column;
    overflow: hidden;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-lg);
    background-color: var(--moduix-color-popover);
    color: var(--moduix-color-popover-foreground);
    box-shadow: var(--moduix-shadow-lg);
    outline: 0;
    transform-origin: top center;

    &[data-state='open'] {
      animation: global(moduix-command-palette-content-in)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out));
    }

    &[data-state='closed'] {
      animation: global(moduix-command-palette-content-out)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out)) forwards;
    }
  }

  .header {
    display: grid;
    gap: var(--moduix-spacing-1);
    padding: var(--moduix-spacing-4) var(--moduix-spacing-4) 0;
  }

  .title {
    margin: 0;
    font-size: var(--moduix-text-md);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-md);
  }

  .description {
    margin: 0;
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
  }

  .combobox {
    display: flex;
    min-height: 0;
    flex: 1 1 auto;
    flex-direction: column;
    overflow: hidden;
  }

  .control {
    box-sizing: border-box;
    display: flex;
    flex: none;
    align-items: center;
    gap: var(--moduix-spacing-2);
    min-height: var(--moduix-size-md);
    margin: var(--moduix-spacing-3) var(--moduix-spacing-3) 0;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    padding: var(--moduix-spacing-1) var(--moduix-spacing-3);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    transition: border-color var(--moduix-transition-default);

    &[data-invalid] {
      border-color: var(--moduix-color-destructive);
    }
  }

  .searchIcon {
    flex: none;
    width: var(--moduix-spacing-4);
    height: var(--moduix-spacing-4);
    color: var(--moduix-color-muted-foreground);
    pointer-events: none;
  }

  .input {
    box-sizing: border-box;
    flex: 1;
    min-width: 0;
    margin: 0;
    border: 0;
    padding: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    outline: 0;

    &::placeholder {
      color: var(--moduix-color-muted-foreground);
    }
  }

  .clearTrigger {
    --moduix-close-button-size: var(--moduix-size-xs);

    &[hidden] {
      display: none;
    }
  }

  .list {
    box-sizing: border-box;
    display: flex;
    flex: 1 1 auto;
    min-height: 0;
    overflow: hidden;
    outline: 0;
  }

  /* `.list >` outranks the ScrollArea root `height: 100%`, which would not stretch in a list capped by max-height. */
  .list > .scrollArea {
    flex: 1 1 auto;
    height: auto;
    min-height: 0;
  }

  .scrollViewport {
    scroll-padding-block: var(--moduix-spacing-2);
  }

  .scrollContent {
    min-height: 100%;
    padding: var(--moduix-spacing-3);
  }

  /* The list already pads the result area; this adds the remaining inline inset. */
  .empty {
    padding-inline: var(--moduix-spacing-1);
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
  }

  .itemGroup {
    display: grid;
    gap: var(--moduix-spacing-1);

    &:not(:last-child) {
      padding-bottom: var(--moduix-spacing-2);
    }
  }

  .itemGroupLabel {
    position: sticky;
    top: 0;
    z-index: 1;
    padding: var(--moduix-popup-group-label-padding-y, var(--moduix-spacing-1))
      var(--moduix-spacing-3);
    background-color: var(--moduix-color-popover);
    color: var(--moduix-popup-group-label-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-popup-group-label-font-size, var(--moduix-text-xs));
    font-weight: var(--moduix-popup-group-label-font-weight, var(--moduix-weight-regular));
    line-height: var(--moduix-popup-group-label-line-height, var(--moduix-line-height-text-xs));
  }

  .item {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    gap: var(--moduix-spacing-3);
    min-height: var(--moduix-popup-item-min-height, var(--moduix-size-sm));
    padding-block: var(--moduix-popup-item-padding-y, var(--moduix-spacing-1));
    padding-inline: var(--moduix-popup-item-padding-x-start, var(--moduix-spacing-3));
    border-radius: var(--moduix-radius-md);
    font-size: var(--moduix-popup-item-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-popup-item-line-height, var(--moduix-line-height-text-sm));
    outline: 0;
    cursor: default;
    user-select: none;

    &[data-highlighted] {
      background-color: var(--moduix-color-accent);
      color: var(--moduix-color-accent-foreground);
    }

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
      pointer-events: none;
    }
  }

  .itemIcon {
    display: inline-flex;
    flex: none;
    width: var(--moduix-spacing-8);
    height: var(--moduix-spacing-8);
    align-items: center;
    justify-content: center;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-md);
    background-color: var(--moduix-color-muted);
    color: var(--moduix-color-muted-foreground);
  }

  .itemText {
    display: grid;
    flex: 1 1 auto;
    min-width: 0;
    gap: var(--moduix-spacing-1);
  }

  .itemLabel,
  .itemDescription {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .itemLabel {
    font-weight: var(--moduix-weight-medium);
  }

  .itemDescription {
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-xs);
    line-height: var(--moduix-line-height-text-xs);
  }

  .itemMeta,
  .itemIndicator {
    flex: none;
    margin-inline-start: auto;
    color: var(--moduix-color-muted-foreground);
  }

  .itemMeta {
    font-size: var(--moduix-text-xs);
    line-height: var(--moduix-line-height-text-xs);
    white-space: nowrap;
  }

  .itemIndicator {
    display: inline-flex;
  }

  .itemIcon > svg,
  .itemIndicator > svg {
    width: var(--moduix-spacing-4);
    height: var(--moduix-spacing-4);
  }

  .separator {
    height: var(--moduix-border-width-sm);
    margin: var(--moduix-spacing-2);
    background-color: var(--moduix-color-border);
  }

  .footer {
    display: flex;
    flex: none;
    align-items: center;
    justify-content: space-between;
    gap: var(--moduix-spacing-3);
    padding: var(--moduix-spacing-2) var(--moduix-spacing-4);
    border-top: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-xs);
    line-height: var(--moduix-line-height-text-xs);
  }

  .kbd {
    --moduix-kbd-height: var(--moduix-spacing-5);
    --moduix-kbd-padding-x: var(--moduix-spacing-1);
    --moduix-kbd-color: var(--moduix-color-muted-foreground);
  }

  @media (prefers-reduced-motion: reduce) {
    .backdrop[data-state],
    .content[data-state] {
      animation: none;
    }
  }
}
